class Solution {
public:
    int catMouseGame(vector<vector<int>>& graph) {
        int n = graph.size();
        vector<vector<array<int, 2>>> result(n, vector<array<int, 2>>(n, {0, 0}));
        vector<vector<array<int, 2>>> degree(n, vector<array<int, 2>>(n, {0, 0}));
        queue<array<int, 3>> q;
        for (int m = 0; m < n; ++m) for (int c = 1; c < n; ++c) {
            degree[m][c][0] = graph[m].size();
            for (int v : graph[c]) if (v != 0) ++degree[m][c][1];
        }
        for (int c = 1; c < n; ++c) for (int t = 0; t < 2; ++t) {
            result[0][c][t] = 1;
            q.push({0, c, t});
        }
        for (int m = 1; m < n; ++m) for (int t = 0; t < 2; ++t) {
            result[m][m][t] = 2;
            q.push({m, m, t});
        }
        while (!q.empty()) {
            auto state = q.front(); q.pop();
            int m = state[0], c = state[1], turn = state[2];
            int winner = result[m][c][turn];
            int previousTurn = 1 - turn;
            const vector<int>& parents = previousTurn == 0 ? graph[m] : graph[c];
            for (int prev : parents) {
                if (previousTurn == 1 && prev == 0) continue;
                int pm = previousTurn == 0 ? prev : m;
                int pc = previousTurn == 1 ? prev : c;
                if (result[pm][pc][previousTurn] != 0) continue;
                if (winner == previousTurn + 1) {
                    result[pm][pc][previousTurn] = winner;
                    q.push({pm, pc, previousTurn});
                } else if (--degree[pm][pc][previousTurn] == 0) {
                    result[pm][pc][previousTurn] = winner;
                    q.push({pm, pc, previousTurn});
                }
            }
        }
        return result[1][2][0];
    }
};
